            { "Uninstall.bat 실행 완료.", "Uninstall.bat finished." }, { "전체 제거 완료", "Uninstalled" },
            { "SRWeave.log가 아직 없습니다 (게임을 한 번 실행하면 생깁니다).", "No SRWeave.log yet (it appears after the game has run once)." }, { "SRWeave.log가 아직 없습니다.", "No SRWeave.log yet." },
